INSERT INTO profession_details (profession_id, reality, pros, cons) VALUES
(120, 'Не "босс, который всё знает". Это 50% конфликтов ("он не так понял"), 30% отчётов, и 20% "а вдруг уволят?". И ответственность за всё — всегда.', '["Влияешь на результат — реально", "Зарплата растёт быстро", "Статус и уважение", "Можно работать в любой сфере"]', '["50% конфликтов", "Ответственность за всё", "12-часовые дни", "Выгорание через 5 лет", "Увольнение — всегда риск"]'),
(121, 'Не "спаситель нации". Это 50% переговоров ("давайте договоримся"), 30% пиара ("посмотрите, какой я хороший"), и 20% предательств ("а вдруг он нас сдаст?").', '["Влияешь на страну — реально", "Статус, уважение, власть", "Нет потолка дохода", "Можно изменить мир"]', '["50% переговоров, не дела", "Предательства — норма", "Постоянный стресс", "Семья страдает", "Выгорание через 5 лет"]'),
(122, 'Не "защитник правды". Это 80% бумаг (договоры, иски), 15% переговоров ("а вдруг договоримся?"), и 5% суда ("ваша честь, я возражаю!").', '["Влияешь на результат — реально", "Зарплата растёт быстро", "Статус и уважение", "Можно работать в любой сфере"]', '["80% бумаг", "Ответственность — ошибка = проигрыш", "12-часовые дни", "Выгорание через 5 лет", "Клиенты врут"]'),
(123, 'Не "креативный гений". Это 50% аналитики (метрики, CTR, ROI), 30% бюджетов ("денег нет, но вы держитесь"), и 20% креатива.', '["Креатив + аналитика", "Виден результат — продажи", "Можно работать в любой сфере", "Удалёнка — норма"]', '["50% аналитики, не креатив", "Бюджеты режут", "Ответственность за продажи", "Выгорание через 3-5 лет", "Босс: а почему не выросло?"]'),
(124, 'Не "креативный гений". Это 50% аналитики (метрики, CTR, ROI), 30% бюджетов ("денег нет, но вы держитесь"), и 20% креатива.', '["Креатив + аналитика", "Виден результат — продажи", "Можно работать в любой сфере", "Удалёнка — норма"]', '["50% аналитики, не креатив", "Бюджеты режут", "Ответственность за продажи", "Выгорание через 3-5 лет", "Босс: а почему не выросло?"]'),
